typedef unsigned int nslSoundId;

typedef enum _nslSoundStatusEnum
{
  NSL_SOUNDSTATUS_INVALID = 0,
  NSL_SOUNDSTATUS_QUEUING,
  NSL_SOUNDSTATUS_READY,
  NSL_SOUNDSTATUS_PLAYING,
  NSL_SOUNDSTATUS_PAUSED
} nslSoundStatusEnum;

struct nslSound
{
  int isReady;
  int used;
  int inRange;
  int isReallyReady;
  int isPlaying;
  int isReallyPlaying;
  int looping;
  int isQueuing;
  short left;
  short right;
  short old_left;
  short old_right;
  unsigned int gasInstanceId;
  int pauseCount;
  int dampenCount;
  unsigned int myId;
  unsigned int mySource;
  unsigned int myEmitter;
  float rawVolume;
  float positionalVolume;
  float angle;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char padding0[0xC040];
  nslSound soundSlots[256];
  char padding1[0x4010];
  int initialized;
  char padding2[44];
  int on;
};

extern nslSystem nsl;
extern const char nsl_not_initialized[];
void nslFatal(const char *format, ...);

__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ nsl_not_initialized, 0x0051BF80");
__asm__(".equ nslFatal__FPCce, 0x00391420");

#define NSL_NUM_SOUNDS 256
#define NSL_ID_MASK 0xFFFFFC00
#define NSL_SLOT_MASK 0x000003FF
#define NSL_GET_SLOT_FROM_ID(x) (x & NSL_SLOT_MASK)
#define NSL_INVALID_ID 0

#define ASSERT_NSL_INITIALIZED() \
  do { if (!(nsl.initialized == 1)) nslFatal(nsl_not_initialized); } while (0)

nslSoundStatusEnum nslGetSoundStatus(nslSoundId whichSound)
{
  if (!nsl.on) return NSL_SOUNDSTATUS_INVALID;
  ASSERT_NSL_INITIALIZED();

  nslSoundId checkSlot = (whichSound & NSL_SLOT_MASK);
  nslSoundId upCheckId = (whichSound & NSL_ID_MASK);

  if (whichSound == NSL_INVALID_ID)
    return NSL_SOUNDSTATUS_INVALID;
  if (!(nsl.soundSlots[checkSlot].used))
    return NSL_SOUNDSTATUS_INVALID;
  if (!(checkSlot < NSL_NUM_SOUNDS))
    return NSL_SOUNDSTATUS_INVALID;
  if (!(whichSound == nsl.soundSlots[checkSlot].myId))
    return NSL_SOUNDSTATUS_INVALID;
  if (!(upCheckId > 0))
    return NSL_SOUNDSTATUS_INVALID;

  if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(whichSound)].pauseCount > 0)
    return NSL_SOUNDSTATUS_PAUSED;

  if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(whichSound)].used &&
      nsl.soundSlots[NSL_GET_SLOT_FROM_ID(whichSound)].isPlaying &&
      (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(whichSound)].pauseCount < 1))
    return NSL_SOUNDSTATUS_PLAYING;

  if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(whichSound)].isReady)
    return NSL_SOUNDSTATUS_READY;

  if (nsl.soundSlots[NSL_GET_SLOT_FROM_ID(whichSound)].isQueuing)
    return NSL_SOUNDSTATUS_QUEUING;

  return NSL_SOUNDSTATUS_INVALID;
}
